1	<#
2	.SYNOPSIS
3	    The detached-run readers of the codex-consult bridge (wave 26, F07-3): dot-sourced by
4	    codex-consult-common.ps1 (so by every script of the plugin) and, alone, by the SessionStart
5	    hook, which needs one phrase about the detached consultations of the repository and should
6	    not parse the whole common script for it.
7	
8	.DESCRIPTION
9	    Contents: a few small helpers the readers need (Read-SharedText, Get-PropertyValue,
10	    ConvertTo-OneLine, Test-IsJsonObject, ConvertTo-JsonText, ConvertTo-WhenOffset,
11	    Get-GitOutput, Resolve-RepoRoot, Resolve-CollabRoot, Get-ProcessStartIso,
12	    Test-SameStartTime, Test-PidAlive, wave 28c: Get-PidIdentity; wave 28e: Get-ProcessStartTicks,
13	    Get-PidIdentityTicks; wave 28: Get-TelemetrySwitch, the switch the hook prints)
14	    and the readers of a detached run's status file
15	    (Get-DetachedPaths, New-DetachedMember, ConvertTo-DetachedTime, ConvertTo-DetachedRecord,
16	    Read-DetachedStatus, Read-DetachedRuns, Format-DetachedSpan, Get-DetachedJudgement,
17	    Format-DetachedListLine, Get-DetachedPhrase). Nothing here writes a file.
18	
19	    Windows PowerShell 5.1 and PowerShell 7 compatible. Keep this file ASCII.
20	#>
21	
22	# The script-scope values the helpers read (codex-consult-common.ps1 sets them first; the hook
23	# does not).
24	if ($null -eq $script:OnWindows) { $script:OnWindows = if ($null -ne $IsWindows) { [bool]$IsWindows } else { $true } }
25	if ($null -eq $script:Utf8NoBom) { $script:Utf8NoBom = New-Object System.Text.UTF8Encoding($false) }
26	if ($null -eq $script:Invariant) { $script:Invariant = [System.Globalization.CultureInfo]::InvariantCulture }
27	
28	# ----------------------------------------------------------------------------- small helpers
29	
30	# Start-Process holds the stdout/stderr redirection handles for a short while after
31	# the child exits, so a plain Get-Content can fail with "the process cannot access
32	# the file ... because it is being used by another process" - observed on a
33	# fast-failing codex run. Read with FileShare.ReadWrite (+ Delete, so an atomic
34	# replace of the file is not blocked by this reader) and retry briefly.
35	function Read-SharedText {
36	    param([string]$Path)
37	    if (-not (Test-Path -LiteralPath $Path)) { return '' }
38	    for ($attempt = 1; $attempt -le 6; $attempt++) {
39	        try {
40	            $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
41	            try {
42	                $sr = New-Object System.IO.StreamReader($fs, (New-Object System.Text.UTF8Encoding($false)), $true)
43	                try { return $sr.ReadToEnd() } finally { $sr.Dispose() }
44	            } finally { $fs.Dispose() }
45	        } catch {
46	            Start-Sleep -Milliseconds 250
47	        }
48	    }
49	    return ''
50	}
51	
52	# Git is optional and every call here is allowed to fail (no repo, no commits yet,
53	# git not installed). Windows PowerShell turns a native command's stderr into a
54	# terminating NativeCommandError while $ErrorActionPreference is 'Stop', so relax it
55	# for the duration of the call and report failure as $null.
56	function Get-GitOutput {
57	    param([string]$Root, [string[]]$GitArgs)
58	    $all = @('-C', $Root) + $GitArgs
59	    $previous = $ErrorActionPreference
60	    $ErrorActionPreference = 'Continue'
61	    try {
62	        $out = & git @all 2>$null
63	        if ($LASTEXITCODE -ne 0) { return $null }
64	        return $out
65	    } catch {
66	        return $null
67	    } finally {
68	        $ErrorActionPreference = $previous
69	    }
70	}
71	
72	# The working directory of the caller is the project being discussed, not the
73	# directory the scripts live in (a plugin installs them outside the project).
74	function Resolve-RepoRoot {
75	    param([string]$Cwd)
76	    $top = Get-GitOutput -Root $Cwd -GitArgs @('rev-parse', '--show-toplevel')
77	    if ($top) {
78	        $first = ([string]@($top)[0]).Trim()
79	        if ($first -and (Test-Path -LiteralPath $first)) {
80	            return (Resolve-Path -LiteralPath $first).Path
81	        }
82	    }
83	    # Not a git repository: fall back to the current directory.
84	    return $Cwd
85	}
86	
87	# Relative -CollabDir resolves against the repository root.
88	function Resolve-CollabRoot {
89	    param([string]$RepoRoot, [string]$CollabDir)
90	    $p = $CollabDir
91	    if (-not [IO.Path]::IsPathRooted($p)) { $p = Join-Path $RepoRoot $p }
92	    return [IO.Path]::GetFullPath($p)
93	}
94	
95	function Get-PropertyValue {
96	    param($Object, [string]$Name, $Default = '')
97	    if ($null -ne $Object -and $Object.PSObject.Properties[$Name] -and $null -ne $Object.$Name) { return $Object.$Name }
98	    return $Default
99	}
100	
101	function ConvertTo-OneLine {
102	    param([string]$Text)
103	    if (-not $Text) { return '' }
104	    return (($Text -replace '\s+', ' ').Trim())
105	}
106	
107	function Test-IsJsonObject {
108	    param($Value)
109	    return ($Value -is [System.Management.Automation.PSCustomObject])
110	}
111	
112	function ConvertTo-JsonText {
113	    param($Value)
114	    if ($null -eq $Value) { return '' }
115	    if ($Value -is [datetime]) { return $Value.ToString('o', $script:Invariant) }
116	    if ($Value -is [DateTimeOffset]) { return $Value.ToString('yyyy-MM-ddTHH:mm:ss.FFFFFFFzzz', $script:Invariant) }
117	    return [string]$Value
118	}
119	
120	function ConvertTo-WhenOffset {
121	    param($Value)
122	    if ($Value -is [DateTimeOffset]) { return $Value }
123	    if ($Value -is [datetime]) { return [DateTimeOffset]$Value }
124	    $at = [DateTimeOffset]::MinValue
125	    if ([DateTimeOffset]::TryParse([string]$Value, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$at)) { return $at }
126	    return $null
127	}
128	
129	# Process start time as a UTC round-trip string. $null: no such process. '': the
130	# process exists but its start time cannot be read (e.g. another user's process).
131	# (wave 28c, D8) TEST HOOK (test mode only): CODEX_CONSULT_TEST_START_UNREADABLE=<pid>[,<pid>] - these
132	# pids, while they exist, read as '' (a start time that cannot be read).
133	function Get-ProcessStartIso {
134	    param([int]$ProcessId)
135	    $p = $null
136	    try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
137	    $unreadable = [string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TEST_START_UNREADABLE')
138	    if ($unreadable -and ([string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TEST_MODE')).Trim() -eq '1') {
139	        if (@($unreadable.Split(',') | ForEach-Object { $_.Trim() }) -contains [string]$ProcessId) { return '' }
140	    }
141	    try { return $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { return '' }
142	}
143	
144	# Do two start times (UTC round-trip strings from Get-ProcessStartIso) name the same
145	# process start? Windows reports a process's start time exactly. .NET on Linux derives
146	# Process.StartTime from a boot time that every process computes for itself
147	# (CLOCK_REALTIME_COARSE - CLOCK_BOOTTIME), so two processes reading the SAME pid get
148	# values a few milliseconds apart. Outside Windows, less than one second apart counts
149	# as the same start (a pid is not handed out again that fast).
150	function Test-SameStartTime {
151	    param([string]$A, [string]$B)
152	    if ($A -eq $B) { return $true }
153	    if ($script:OnWindows) { return $false }
154	    $ta = [DateTimeOffset]::MinValue
155	    $tb = [DateTimeOffset]::MinValue
156	    $styles = [System.Globalization.DateTimeStyles]::AssumeUniversal
157	    if (-not [DateTimeOffset]::TryParse($A, $script:Invariant, $styles, [ref]$ta)) { return $false }
158	    if (-not [DateTimeOffset]::TryParse($B, $script:Invariant, $styles, [ref]$tb)) { return $false }
159	    return ([math]::Abs($ta.UtcTicks - $tb.UtcTicks) -lt [TimeSpan]::TicksPerSecond)
160	}
161	
162	# (wave 28c, D8 / F42-4) The identity of a pid against the start time read for it before: 'alive' (a
163	# process with this pid exists AND has that start time), 'gone' (no such process, or one with another
164	# start time - the pid was handed to another process), 'unknown' (a process with this pid exists, but
165	# the start time recorded or the one read now is unreadable - its identity cannot be confirmed). A
166	# KILL acts on 'alive' only and never counts 'unknown' as gone (Stop-ProcessTreeChecked); a holder of
167	# a lock or a record counts as alive on 'unknown' (Test-PidAlive: never taken over on a guess).
168	function Get-PidIdentity {
169	    param([int]$ProcessId, [string]$StartTime = '')
170	    if ($ProcessId -le 0) { return 'gone' }
171	    $live = Get-ProcessStartIso -ProcessId $ProcessId
172	    if ($null -eq $live) { return 'gone' }
173	    if (-not $StartTime -or -not $live) { return 'unknown' }
174	    if (Test-SameStartTime -A $live -B $StartTime) { return 'alive' }
175	    return 'gone'
176	}
177	
178	# A pid counts as alive when a process with that id exists and - if a start time was
179	# recorded for it - still has that start time (otherwise the pid was reused). (wave 28c, D8) An
180	# identity that cannot be confirmed ('unknown' of Get-PidIdentity) counts as ALIVE here: a holder is
181	# never taken over, a survivor never released, on a guess.
182	function Test-PidAlive {
183	    param([int]$ProcessId, [string]$StartTime = '')
184	    if ($ProcessId -le 0) { return $false }
185	    $live = Get-ProcessStartIso -ProcessId $ProcessId
186	    if ($null -eq $live) { return $false }
187	    if ($StartTime -and $live -and -not (Test-SameStartTime -A $live -B $StartTime)) { return $false }
188	    return $true
189	}
190	
191	# (wave 28e, E3 / F54-3) A process's start time as a whole number of ticks (UTC, 100 ns - the full
192	# resolution Windows reports; read through Get-ProcessStartIso, so its test hook applies): $null - no
193	# such process; -1 - the process exists but its start time cannot be read; else the ticks.
194	function Get-ProcessStartTicks {
195	    param([int]$ProcessId)
196	    if ($ProcessId -le 0) { return $null }
197	    $iso = Get-ProcessStartIso -ProcessId $ProcessId
198	    if ($null -eq $iso) { return $null }
199	    $t = [DateTimeOffset]::MinValue
200	    if ($iso -and [DateTimeOffset]::TryParse($iso, $script:Invariant, [System.Globalization.DateTimeStyles]::AssumeUniversal, [ref]$t)) { return [long]$t.UtcTicks }
201	    return [long]-1
202	}
203	
204	# (wave 28e, E3, E2) The identity of a pid against the start ticks recorded for it (Get-ProcessStartTicks):
205	# 'alive' (a process with this pid runs with EXACTLY those ticks - outside Windows within the same
206	# second, the jitter Test-SameStartTime explains), 'gone' (no such process, or one with another start:
207	# the pid was handed to another process), 'unknown' (no ticks were recorded, or the start time cannot
208	# be read now). A holder counts as alive on 'unknown' - never removed on a guess.
209	function Get-PidIdentityTicks {
210	    param([int]$ProcessId, [long]$StartTicks = 0)
211	    if ($ProcessId -le 0) { return 'gone' }
212	    $live = Get-ProcessStartTicks -ProcessId $ProcessId
213	    if ($null -eq $live) { return 'gone' }
214	    if ($StartTicks -le 0 -or $live -lt 0) { return 'unknown' }
215	    if ($live -eq $StartTicks) { return 'alive' }
216	    if (-not $script:OnWindows -and [math]::Abs($live - $StartTicks) -lt [TimeSpan]::TicksPerSecond) { return 'alive' }
217	    return 'gone'
218	}
219	
220	# (wave 28, R17) The telemetry switch - shared with the SessionStart hook, which prints it. A run's
221	# -Telemetry on|off ($Override) wins; else CODEX_CONSULT_TELEMETRY: unset or empty - ON (the
222	# default); on, 1, true, yes - on; off, 0, false, no, none - off; ANY OTHER VALUE counts as off (a
223	# switch that cannot be read never sends). Reads the environment only. { On; Text ('on' | 'off');
224	# Source ('-Telemetry' | 'the default' | 'CODEX_CONSULT_TELEMETRY' | ... (not on or off: counts as
225	# off)) }.
226	function Get-TelemetrySwitch {
227	    param([string]$Override = '')
228	    $o = ([string]$Override).Trim().ToLowerInvariant()
229	    if ($o -eq 'on' -or $o -eq 'off') { return [pscustomobject]@{ On = ($o -eq 'on'); Text = $o; Source = '-Telemetry' } }
230	    $v = ([string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TELEMETRY')).Trim().ToLowerInvariant()
231	    if (-not $v) { return [pscustomobject]@{ On = $true; Text = 'on'; Source = 'the default' } }
232	    if (@('on', '1', 'true', 'yes') -contains $v) { return [pscustomobject]@{ On = $true; Text = 'on'; Source = 'CODEX_CONSULT_TELEMETRY' } }
233	    if (@('off', '0', 'false', 'no', 'none') -contains $v) { return [pscustomobject]@{ On = $false; Text = 'off'; Source = 'CODEX_CONSULT_TELEMETRY' } }
