294	# A timestamp field back as text ($null for none): a [datetime] or [DateTimeOffset] that
295	# ConvertFrom-Json made of it (PowerShell 7) returns to the bridge's own form - the local ISO
296	# form of Get-IsoTimestamp, or (-RoundTrip) the UTC round trip of Get-ProcessStartIso.
297	function ConvertTo-DetachedTime {
298	    param($Value, [switch]$RoundTrip)
299	    if ($null -eq $Value -or ($Value -is [string] -and -not $Value)) { return $null }
300	    if ($RoundTrip) { return (ConvertTo-JsonText $Value) }
301	    $at = ConvertTo-WhenOffset $Value
