463	# The line codex-findings.ps1 -List prints for a detached run of the task that is not done ('' for
464	# a done one): `detached <id8>: running since <t>, k of N members finished`, or its died,
465	# starting, never-started or other-host wording (D6), with the command that shows it.
466	function Format-DetachedListLine {
467	    param($Run, [string]$Task, [DateTimeOffset]$Now = [DateTimeOffset]::Now)
468	    $j = Get-DetachedJudgement -Record $Run.Record -Problem ([string]$Run.Error) -Now $Now
469	    if ($j.State -eq 'done') { return '' }
470	    return "detached $($Run.Id8): $($j.Text) (codex-consult.ps1 -Task $Task -Status -Id $($Run.Id8))"
471	}
