            } finally { $fs.Dispose() }
            try { return (([string](Get-PropertyValue (ConvertFrom-Json -InputObject $text) 'token' '')) -ceq $Token) } catch { return $false }
        } catch { Start-Sleep -Milliseconds 50 }
    }
    return $false
}

